package owl.nh;
import java.util.*;
import net.runelite.api.*;
import net.runelite.api.widgets.*;
public final class OlmPoolTests {
 static void check(boolean ok,String message){CoreTests.check(ok,"Olm pools/rewards: "+message);}
 static OlmSpecials.Cell c(int x,int y){return new OlmSpecials.Cell(x,y,0);}
 public static void main(String[] args){
  Set<OlmSpecials.Cell> pools=new HashSet<>(Arrays.asList(c(2,0),c(9,0)));OlmPoolDuty duty=new OlmPoolDuty();
  for(int tick=100;tick<110;tick++){for(int cycle=0;cycle<30;cycle++)duty.observe(tick,tick<102?c(0,0):c(2,0),pools);if(tick==109)check(duty.active()&&duty.occupied()==8,"eight real tick samples meet the minimum without ending the hold early");}
  duty.observe(110,c(2,0),Collections.emptySet());check(((Number)duty.diagnostics(110).get("windowsMeetingMinimum")).intValue()==1&&!duty.active(),"disappearance releases the hold and records an eight-of-ten window");
  duty.reset();duty.observe(200,c(0,0),pools);duty.observe(205,c(2,0),pools);duty.observe(209,c(2,0),pools);duty.observe(210,c(2,0),Collections.emptySet());check(duty.occupied()==2&&((Number)duty.diagnostics(210).get("windowsBelowMinimum")).intValue()==1,"missing observations never fabricate successful occupancy");
  duty.reset();duty.observe(300,c(2,0),pools);duty.observe(301,c(9,0),Collections.singleton(c(9,0)));check(duty.occupied()==2&&duty.active(),"either live pool counts without resetting when the other disappears");duty.cancel();check(((Number)duty.diagnostics(301).get("completedWindows")).intValue()==0,"manual cancellation is not a completed successful window");
  duty.reset();duty.observe(400,c(2,0),pools);for(int tick=401;tick<410;tick++)duty.observe(tick,c(2,0),Collections.emptySet());check(duty.active()&&duty.occupied()==10,"brief or early visual loss cannot abandon the user-defined ten-tick pool window");duty.observe(410,c(2,0),Collections.emptySet());check(!duty.active(),"release after the ten-tick window when the effect is gone");
  OlmMechanicAdapter.Config config=new OlmMechanicAdapter.Config();check(config.healingPoolProjectiles.contains(1355)&&OlmMechanicAdapter.healingPoolGraphic(config,1363,OlmStrategy.Phase.HEAD)&&!OlmMechanicAdapter.healingPoolGraphic(config,1363,OlmStrategy.Phase.REGULAR),"head-only heal-pool floor signal cannot turn a hand-phase effect into a safe pool");
  Map<String,Object> actorFields=new HashMap<>();actorFields.put("getWorldLocation",new net.runelite.api.coords.WorldPoint(2,0,0));Player player=ChambersTests.fake(Player.class,actorFields);Map<String,Object> clientFields=new HashMap<>();clientFields.put("getLocalPlayer",player);clientFields.put("getTickCount",100);Client client=ChambersTests.fake(Client.class,clientFields);OlmMechanicAdapter adapter=new OlmMechanicAdapter(client);adapter.configure(new OlmFighter.Profile());adapter.start();OlmSpecials.View view=new OlmSpecials.View();view.player=c(2,0);view.tick=100;view.hazards.add(new OlmSpecials.Hazard(view.player,OlmSpecials.HazardKind.FALLING,2));view.hazards.add(new OlmSpecials.Hazard(view.player,OlmSpecials.HazardKind.ELECTRIC,0));check(adapter.handleHealingPools(OlmStrategy.Phase.HEAD,view,pools)&&adapter.poolPriority()&&adapter.inHealingPool(),"production pool duty takes precedence over simultaneous ordinary dodges and attack requests");view.tick=110;check(!adapter.handleHealingPools(OlmStrategy.Phase.HEAD,view,Collections.emptySet())&&!adapter.poolPriority(),"normal combat resumes when the pool disappears");
  rewardLayouts();System.out.println("Olm healing-pool checks passed: 8/10 observed ticks, no duplicate/missing-tick credit, hold until disappearance, overlapping danger priority and dynamic reward layouts. Synthetic only.");
 }
 static void rewardLayouts(){
  check(!OlmRaidFinish.needsSpace(28,true,true)&&OlmRaidFinish.needsSpace(28,false,true)&&!OlmRaidFinish.needsSpace(27,false,false),"full bags allow existing stacks and only require a drop for an actual missing slot");check(OlmRaidFinish.mayDropAid(Arrays.asList(20984),20984,"Xeric's aid (+)(4)",true)&&!OlmRaidFinish.mayDropAid(Arrays.asList(20984),20984,"Twisted bow",true)&&!OlmRaidFinish.mayDropAid(Arrays.asList(20984),1,"Xeric's aid",true),"drop permission is restricted to configured, live-named droppable Xeric's aids");
  Map<String,Object> parentFields=new HashMap<>();parentFields.put("isVisible",true);Widget parent=ChambersTests.fake(Widget.class,parentFields);Map<String,Object> slotFields=new HashMap<>();slotFields.put("isVisible",true);slotFields.put("getParent",parent);slotFields.put("getItemId",566);slotFields.put("getItemQuantity",10);slotFields.put("getBounds",new java.awt.Rectangle(10,10,32,32));Widget slot=ChambersTests.fake(Widget.class,slotFields);parentFields.put("getDynamicChildren",new Widget[]{slot});parentFields.put("getChildren",new Widget[]{slot});OlmRewardView result=OlmRewardView.read(parent);check(result.visible&&result.readable&&result.items.size()==1&&result.items.get(0).id==566,"dynamic Take widgets work when legacy getWidgetItems is null, with duplicate children suppressed");parentFields.put("isHidden",true);check(!OlmRewardView.read(parent).visible,"cached child visibility cannot collect through a hidden reward parent");parentFields.put("isHidden",false);parentFields.put("getChildren",null);parentFields.put("getDynamicChildren",new Widget[0]);check(OlmRewardView.read(parent).readable&&OlmRewardView.read(parent).items.isEmpty(),"actual empty dynamic container remains observable");parentFields.put("getDynamicChildren",null);check(!OlmRewardView.read(parent).readable,"unavailable layout is distinct from a verified empty chest");
 }
}
